{
    let res: i8;
    if n % k == 0i8 {
        res = 0i8;
    } else {
        res = 1i8;
    }
    proof {
        lemma_i8_mod_zero_equiv(n, k);
        if n % k == 0i8 {
            assert((n as int) % (k as int) == 0);
            assert(res as int == 0);
            assert(res as int == min_cracker_difference(n as int, k as int));
        } else {
            assert((n as int) % (k as int) != 0);
            assert(res as int == 1);
            assert(res as int == min_cracker_difference(n as int, k as int));
